const outputs = artifact?.structuredOutputs && typeof artifact.structuredOutputs === 'object' ? artifact.structuredOutputs : {};
const outputEntries = Object.entries(outputs);
const findOutputByCanonicalName = (canonicalName) => outputEntries.find(([, item]) => normalizeName(item?.name) === canonicalName) || null;
const readBooleanOutput = (canonicalName, fallback = null) => {
  const match = findOutputByCanonicalName(canonicalName);
  return typeof match?.[1]?.result === 'boolean' ? match[1].result : fallback;
};
const outputEntry = outputs[configuredOutputId] || findOutputByCanonicalName('Dental Call Intake')?.[1] || null;
const result = outputEntry?.result || null;
const qualityFlags = result?.qualityFlags || {};
const riskFlags = result?.riskFlags || {};
const qaSignals = {
  successfulForAssistantScope: readBooleanOutput('QA: Scope OK', typeof result?.successfulForAssistantScope === 'boolean' ? result.successfulForAssistantScope : null),
  medicalAdviceGiven: readBooleanOutput('QA: Medical Advice Given', riskFlags.medicalAdviceGiven === true),
  toolFailureOccurred: readBooleanOutput('QA: Tool Failure', riskFlags.toolFailureOccurred === true),
  repeatedIdentityRequest: readBooleanOutput('QA: Repeated Identity', typeof qualityFlags.repeatedIdentityRequest === 'boolean' ? qualityFlags.repeatedIdentityRequest : null),
  explicitBookingConfirmationMissing: readBooleanOutput('QA: Booking Confirm Missing'),
  phoneNumberRepeatedIncorrectly: readBooleanOutput('QA: Phone Readback Wrong'),
  multipleQuestionsInSingleTurn: readBooleanOutput('QA: Stacked Questions'),
  toolCalledOnIncompleteAnswer: readBooleanOutput('QA: Premature Tool Call', typeof qualityFlags.toolCalledOnIncompleteAnswer === 'boolean' ? qualityFlags.toolCalledOnIncompleteAnswer : null)
};
const rawScorecards = artifact?.scorecards && typeof artifact.scorecards === 'object' ? artifact.scorecards : {};
const scorecards = Object.entries(rawScorecards).map(([scorecardId, item]) => ({
  scorecardId,
  name: typeof item?.name === 'string' ? item.name : null,
  nameCanonical: normalizeName(item?.name),
  score: typeof item?.score === 'number' ? item.score : null,
  scoreNormalized: typeof item?.scoreNormalized === 'number' ? item.scoreNormalized : null
})).sort((left, right) => (left.name || left.scorecardId).localeCompare(right.name || right.scorecardId));
const reviewReasons = [];
let reviewSeverity = 'none';
const raiseSeverity = (candidate) => {
  const rank = { none: 0, low: 1, medium: 2, high: 3 };
  if ((rank[candidate] || 0) > (rank[reviewSeverity] || 0)) {
    reviewSeverity = candidate;
  }
};
const addReview = (code, severity) => {
  reviewReasons.push(code);
  raiseSeverity(severity);
};
if (!result) {
  addReview('structured_output_missing', 'high');
}
if (qaSignals.medicalAdviceGiven === true) {
  addReview('medical_advice_given', 'high');
}
if (qaSignals.toolFailureOccurred === true) {
  addReview('tool_failure', 'high');
}
if (qaSignals.toolCalledOnIncompleteAnswer === true) {
  addReview('premature_tool_call', 'high');
}
if (qaSignals.explicitBookingConfirmationMissing === true) {
  addReview('booking_confirmation_missing', 'high');
}
