  const scorecardName = scorecard.nameCanonical || scorecard.name || scorecard.scorecardId;
  if (scorecard.scoreNormalized < 70) {
    addReview(`${scorecardName}_critical`, 'high');
  } else if (scorecard.scoreNormalized < 85) {
    addReview(`${scorecardName}_warn`, 'medium');
  }
}
const requiresReview = reviewReasons.length > 0;
