const isEndedStatusUpdate = eventType === 'status-update' && status === 'ended';
const validEvent = (isDirectCallEnded || isEndOfCallReport || isEndedStatusUpdate) && Boolean(callId);
const authenticated = !configuredWebhookSecret || providedWebhookSecret === configuredWebhookSecret;
