  route = 'needs_reception_follow_up';
  reason = followUpNeeded ? 'structured_output_follow_up' : urgentSymptoms ? 'urgent_symptoms' : callOutcome || 'follow_up_required';
} else if (bookingCreated || callOutcome === 'appointment_booked') {
  route = 'booked';
  reason = 'booking_created';
} else if (!result) {
  reason = 'structured_output_missing';
} else {
  reason = callOutcome || 'no_follow_up_needed';
}
return [{ json: {
  ok: authenticated && validEvent,
  eventType,
  status,
  endedReason,
  callId,
  assistantId: call?.assistantId || null,
  customer: payload.customer || message?.customer || call?.customer || null,
  startedAt: call?.startedAt || null,
  endedAt: call?.endedAt || null,
  structuredOutputId: configuredOutputId,
  structuredOutputFound: Boolean(result),
  structuredOutputName: outputEntry?.name || null,
  route,
  reason,
  callOutcome,
  bookingCreated,
  followUpNeeded,
  urgentSymptoms,
  requiresReview,
  reviewSeverity,
  reviewReasons,
  scorecards,
  qaSignals,
